update calendar_private.calendar_days set challenge='{"type":"quiz","visual":"river-path","placeholder":false,"version":"samoggia-river-v2","title":"Dove arriva il Samoggia?","instructions":"Parti dal punto verde del Fiume Samoggia, in basso a sinistra, e segui il corso d’acqua fino a uno dei tre arrivi a destra. Agli incroci continua sulla stessa linea, senza cambiare ramo. Scegli la destinazione e poi conferma.","options":["Fiume Reno","Laghetti di Calderara","Modena"],"correct_index":0,"hint":"Riparti dal punto verde in basso a sinistra. Segui con calma tutte le anse: il percorso può anche tornare indietro. Agli incroci prosegui sulla stessa linea, senza svoltare sull’altra.","explanation":"Il percorso conduce al fiume Reno, dove confluiscono le acque del torrente Samoggia.\n\nMa quando arriva molta acqua, per esempio dopo piogge intense, cosa succede? Lungo il torrente si trova una cassa di espansione: un’area predisposta per accogliere temporaneamente parte dell’acqua durante le piene e ridurre la quantità che prosegue verso valle.\n\nQui lo spazio lasciato all’acqua è diventato anche spazio per la natura: zone umide, prati, arbusti e boschi offrono ambienti diversi agli animali della pianura.","sources":[{"title":"GIAPP — Cassa di espansione del Torrente Samoggia","url":"https://naturadipianura.it/luoghi/cassa-di-espansione-del-torrente-samoggia/"},{"title":"Turismo in Pianura — La cassa del Samoggia","url":"https://turismoinpianura.cittametropolitana.bo.it/it/luoghi/parchi-e-giardini/cassa-di-espansione-del-torrente-samoggia"},{"title":"Regione Emilia-Romagna — Il bacino del Samoggia","url":"https://servizissiir.regione.emilia-romagna.it/deliberegiunta/servlet/AdapterHTTP?ENTE=1&action_name=ACTIONRICERCADELIBERE&codProtocollo=GPG%2F2025%2F1793&operation=downloadTesto"}],"image":"images/giochi/samoggia-percorsi.png"}'::jsonb where day=17;
